using System;

namespace Gori.CompressedStatics;

/// <summary>
/// Selects the transformations performed by the C# rewriter input transformer.
/// </summary>
[Flags]
public enum CSharpRewriterOptions
{
    /// <summary>
    /// Disable all transformations.
    /// </summary>
    None = 0,

    /// <summary>
    /// Change public top-level types to internal.
    /// </summary>
    RewritePublicToInternal = 1 << 0,

    /// <summary>
    /// Add the generated-code attribute to types.
    /// </summary>
    AddAutoGeneratedAttribute = 1 << 1,

    /// <summary>
    /// Add an auto-generated source header.
    /// </summary>
    AddAutoGeneratedHeader = 1 << 2,

    /// <summary>
    /// Add the embedded attribute to types.
    /// </summary>
    AddEmbeddedAttribute = 1 << 3,

    /// <summary>
    /// Insert <c>#nullable enable</c> if the source has nullable property types and no nullable directives.
    /// </summary>
    AddNullableDirective = 1 << 4,

    /// <summary>
    /// Globally qualify resolvable named types, preserving predefined keywords.
    /// </summary>
    RewriteTypeNames = 1 << 5,

    /// <summary>
    /// Remove resolvable imports despite binding errors when type name rewriting is enabled.
    /// </summary>
    AggressiveImportRemoval = 1 << 6,

    /// <summary>
    /// Rewrite supported extension method invocations as fully qualified static calls.
    /// </summary>
    RewriteExtensionCalls = 1 << 7,

    /// <summary>
    /// Add compilation global usings used by the source as ordinary file-level usings.
    /// </summary>
    AddGlobalUsings = 1 << 8,

    /// <summary>
    /// Internalize public top-level types, add the source header and embedded attribute, and materialize used global usings.
    /// </summary>
    Basic = RewritePublicToInternal | AddAutoGeneratedHeader | AddEmbeddedAttribute | AddNullableDirective | AddGlobalUsings,

    /// <summary>
    /// Enable basic transformations, generated-code attributes, global names, and extension call rewriting.
    /// </summary>
    Default = Basic | AddAutoGeneratedAttribute | RewriteTypeNames | RewriteExtensionCalls,

    /// <summary>
    /// Enable every transformation, including resolvable import removal despite binding errors.
    /// </summary>
    All = Default | AggressiveImportRemoval,
}
